add_action( 'pre_get_posts', 'perfectpixel_exclude_category_from_search' );

function perfectpixel_exclude_category_from_search( $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
		return;
	}
	$ids = wp_parse_id_list( '{{search_excluded_category_ids}}' );
	if ( ! $ids ) {
		return;
	}
	$tax_query   = (array) $query->get( 'tax_query' );
	$tax_query[] = array(
		'taxonomy' => 'product_cat',
		'field'    => 'term_id',
		'terms'    => $ids,
		'operator' => 'NOT IN',
	);
	$query->set( 'tax_query', $tax_query );
}
